import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

// Nested value object embedded on the entity — persisted as-is, never validated.
class Address {
  street: string;
  city: string;
  zip: string;
}

@Entity()
export class UserEntity {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  name: string;

  @Column()
  email: string;

  @Column()
  age: number;

  // Internal bookkeeping column — was never meant to be client-settable.
  @Column({ default: false })
  isAdmin: boolean;

  @Column(() => Address)
  address: Address;
}

import {
  BadRequestException,
  Body,
  Controller,
  Get,
  Post,
  Query,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';

@Controller('users')
export class UsersController {
  constructor(
    @InjectRepository(UserEntity)
    private readonly userRepository: Repository<UserEntity>,
  ) {}

  @Post()
  async create(@Body() body: UserEntity) {
    // Scattered inline guards, invented ad hoc for this one handler.
    if (!body.name) {
      throw new BadRequestException('name required');
    }
    if (!body.email) {
      throw new BadRequestException('email required');
    }
    // No email format check, no address.zip check, no allowlist —
    // whatever the client sent (including isAdmin) rides straight through.
    return this.userRepository.save(body);
  }

  @Get()
  async list(@Query('minAge') minAge) {
    // minAge is still a string on the wire — never coerced to a number.
    const users = await this.userRepository.find();
    return users.filter((user) => user.age >= minAge);
  }
}

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  // No app.useGlobalPipes(new ValidationPipe(...)) — no global validation
  // layer, no DTOs, no class-validator decorators anywhere in this module.
  await app.listen(3000);
}
bootstrap();
